{
  "name": "CPU片上温度传感器",
  "name_en": "CPU On-Die Temperature Sensor",
  "manufacturer": "",
  "description": "集成在处理器芯片内部的温度传感器，用于读取CPU热区温度。在实验室和计算平台中可用于热管理、过温告警、散热评估，以及负载测试过程中的温升监测。",
  "description_en": "An integrated temperature sensor inside the processor used to read the CPU thermal-zone temperature. In laboratory and computing setups, it is used for thermal management, over-temperature alarms, cooling evaluation, and temperature-rise monitoring during load testing.",
  "tag_hints": [
    "CPU temperature monitoring",
    "on-die thermal sensor",
    "overheat detection",
    "thermal management",
    "system health monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-temperature",
      "description": "获取CPU当前温度",
      "description_en": "Get the current CPU temperature"
    },
    {
      "action_name": "auto-value",
      "description": "获取归一化温度值",
      "description_en": "Get the normalized temperature value"
    },
    {
      "action_name": "auto-is_active",
      "description": "获取温度是否超过阈值",
      "description_en": "Get whether the temperature is above the threshold"
    },
    {
      "action_name": "auto-closed",
      "description": "获取设备是否已关闭",
      "description_en": "Get whether the device is closed"
    },
    {
      "action_name": "auto-event_delay",
      "description": "获取轮询间隔",
      "description_en": "Get the polling interval"
    },
    {
      "action_name": "auto-wait_for_active",
      "description": "等待温度状态变为活动",
      "description_en": "Wait until the temperature state becomes active"
    },
    {
      "action_name": "auto-wait_for_inactive",
      "description": "等待温度状态变为非活动",
      "description_en": "Wait until the temperature state becomes inactive"
    },
    {
      "action_name": "auto-host",
      "description": "获取已配置的主机地址（如适用）",
      "description_en": "Get the configured host address, if applicable"
    },
    {
      "action_name": "auto-load_average",
      "description": "获取CPU负载平均值（如适用）",
      "description_en": "Get the CPU load average, if applicable"
    },
    {
      "action_name": "auto-start_time",
      "description": "获取开始时间设置（如适用）",
      "description_en": "Get the start time setting, if applicable"
    },
    {
      "action_name": "auto-end_time",
      "description": "获取结束时间设置（如适用）",
      "description_en": "Get the end time setting, if applicable"
    },
    {
      "action_name": "auto-utc",
      "description": "获取是否使用UTC时间（如适用）",
      "description_en": "Get whether UTC time is used, if applicable"
    },
    {
      "action_name": "auto-usage",
      "description": "获取磁盘使用率（如适用）",
      "description_en": "Get the disk usage, if applicable"
    }
  ]
}

